    25: { name: 'Uttara Bhadrapada', meaning: 'Ahir Budhnya, derinlerin yılanı: derinlik, bilgelik, ölçülülük ve istikrar.' },
    26: { name: 'Revati', meaning: 'Çoban Pushan: besleme, güvenli yolculuklar, merhamet ve tamamlanma.' }
